def faq():
    crumbs = [("Home", "index.html"), ("Domande frequenti", "")]
    nav = " · ".join(f'<a href="#faq-{i}">{esc(g)}</a>' for i, (g, _) in enumerate(FAQ))
    groups = "".join(f'''<div class="faq-group" id="faq-{i}"><h2 class="h2">{esc(g)}</h2><div class="faq">{"".join(
        f'<details><summary>{esc(q)}</summary><div class="ans">{"".join(f"<p>{esc(a)}</p>" for a in ans)}</div></details>' for q, ans in qs)}</div></div>'''
                     for i, (g, qs) in enumerate(FAQ))
    body = f'''
<section class="page-hero"><div class="wrap" style="display:grid;gap:16px">{breadcrumb_html(crumbs)}
  <h1 class="h1">Domande frequenti</h1>
  <p class="lead">Orari, biglietti, bagagli e condizioni di viaggio su tutte le linee Sun Lines.</p>
  <p class="small">{nav}</p>
</div></section>
<section class="section section-white"><div class="wrap">{groups}
  <div class="panel" style="margin-top:32px;grid-template-columns:minmax(0,1fr) auto;align-items:center"><div><h2 class="h3">Non trovi la risposta?</h2><p class="small muted">Scrivici: WhatsApp <span class="tnum">{WA_DISPLAY}</span> · {EMAIL}</p></div><a class="btn btn-wa" href="{WA["general"]}">{icon("chat",18)} WhatsApp</a></div>
</div></section>'''
    fp = {"@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": " ".join(ans)}} for _, qs in FAQ for q, ans in qs]}
    ld = jsonld(ORG, fp, breadcrumb_ld([("Home", "/"), ("Domande frequenti", "/domande-frequenti")]))
    return page(slug="faq", title="Domande frequenti su linee, biglietti e bagagli | Sun Lines",
                desc="Risposte su orari, calendario delle linee 20, 30, 50 e 90, biglietti a bordo e online, bagagli, biciclette, minori e oggetti smarriti sui bus Sun Lines.",
                canonical_path="/domande-frequenti", active=None, body=body, ld=ld)


def abbonamenti():
    crumbs = [("Home", "index.html"), ("Linee e orari", "linee-e-orari.html"), ("Abbonamenti studenti", "")]
    body = f'''
<section class="page-hero"><div class="wrap hero-grid">
  <div class="hero-copy">{breadcrumb_html(crumbs)}
    <p class="label eyebrow">Linea 50 · Olbia – Sant’Antonio di Gallura</p>
    <h1 class="h1">Abbonamenti studenti Linea 50</h1>
    <p class="lead">Richiedi online il tuo abbonamento. Possono richiedere l’abbonamento agevolato gli studenti fino a 27 anni.</p>
    <div class="actions"><a class="btn btn-primary" href="{SHOP}">Richiedi l’abbonamento online {icon("external",16)}</a></div>
  </div>
  {photo("Studente con smartphone accanto a un minibus Sun Lines", "attuale", "16/10", eager=True, src="abbonamenti-studenti")}
</div></section>
<section class="section section-white"><div class="wrap grid grid-2" style="align-items:start">
  <div class="prose">
    <p>Per acquistare un abbonamento studenti della Linea 50 (Olbia-Sant'Antonio di Gallura) devi prima creare e completare il profilo del passeggero che utilizzerà l’abbonamento.</p>
    <p>Nel profilo dovrai inserire i dati del passeggero, scegliere la categoria tariffaria corretta e caricare i documenti necessari per ottenere l’agevolazione spettante.</p>
  </div>
  <div class="panel"><h2 class="h3">Prima di iniziare</h2><p class="small">Prepara la seguente documentazione:</p>
    <ul class="small" style="margin:0;padding-left:1.2em;display:grid;gap:6px">
    <li>documento di identità del passeggero, fronte e retro;</li>
    <li>certificazione di iscrizione scolastica oppure <a href="{BASE}/pdf/modulo-autocertificazione.pdf">modulo di autocertificazione</a>, firmato dallo studente se maggiorenne o da un genitore se minorenne;</li>
    <li>documento di identità del genitore, se lo studente è minorenne;</li>
    <li>attestazione ISEE in corso di validità con valore inferiore a € 25.501, richiesta esclusivamente per la tariffa Studente – Ridotta 80%.</li></ul>
    <p class="small muted">Gli allegati possono essere caricati in formato PDF, PNG o JPG e non devono superare 2 MB per file.</p></div>
</div></section>
<section class="section"><div class="wrap">
  <div class="sec-head"><p class="label eyebrow">Come richiedere l’abbonamento</p><h2 class="h1">Due passaggi</h2></div>
  <div class="grid grid-2" style="align-items:start">
    <article class="panel"><p class="label muted">Passaggio 1</p><h3 class="h2">Registrati e completa il profilo</h3>
      <p>Accedi al portale abbonamenti Sun Lines e crea il profilo del passeggero. Nella sezione <strong>Il mio Profilo</strong>:</p>
      <ul style="margin:0;padding-left:1.2em;display:grid;gap:6px"><li>inserisci tutti i dati richiesti;</li><li>scatta la foto tramite la fotocamera del dispositivo;</li><li>seleziona la categoria Studente – Ridotta 60% oppure Studente – Ridotta 80%;</li><li>nella sezione Allegati, carica tutti i documenti previsti per la categoria scelta;</li><li>accetta le dichiarazioni richieste;</li><li>seleziona Salva.</li></ul>
      <p><strong>Prima di salvare il profilo, assicurati di aver caricato tutta la documentazione richiesta. I documenti sono indispensabili per verificare i requisiti e riconoscere l’agevolazione selezionata.</strong></p>
      <p class="small">I dati e i documenti devono appartenere alla persona che utilizzerà l’abbonamento. La documentazione deve essere completa, leggibile e in corso di validità.</p>
      <p class="small">La richiesta deve essere presentata con almeno 48 ore di anticipo rispetto al primo utilizzo previsto dell’abbonamento. Il termine è necessario per verificare i dati e la completezza della documentazione e per lavorare la richiesta.</p></article>
    <article class="panel"><p class="label muted">Passaggio 2</p><h3 class="h2">Acquista l’abbonamento</h3>
      <p>Dopo aver completato e salvato il profilo, torna nella sezione <strong>Abbonamenti</strong>. Puoi consultare le <a href="{BASE}/pdf/tariffe-abbonamento-studenti-sun-lines.pdf">tariffe agevolate degli abbonamenti studenti</a>.</p>
      <ul style="margin:0;padding-left:1.2em;display:grid;gap:6px"><li>Scegli l’abbonamento mensile oppure annuale.</li><li>Seleziona la fermata di partenza e Olbia come destinazione.</li><li>Controlla la tratta e la tariffa applicata.</li><li>Completa il pagamento online.</li></ul>
      <p>Al termine dell’acquisto, l’abbonamento digitale sarà disponibile nell’area personale con QR Code dinamico.</p>
      <p>L’abbonamento deve essere convalidato a bordo a ogni viaggio tramite il QR Code dinamico.</p></article>
  </div>
</div></section>
<section class="section section-white"><div class="wrap grid grid-2" style="align-items:start">
  <div class="prose"><h2 class="h2">Importante</h2>
    <p>La categoria tariffaria viene scelta durante la creazione del profilo. Prima di procedere all’acquisto, verifica di aver selezionato la categoria corretta e caricato tutti i relativi documenti.</p>
    <p>L’utente è responsabile della veridicità dei dati dichiarati, dei documenti caricati, compreso il valore ISEE, e della categoria selezionata.</p>
    <p>Sun Lines si riserva di verificare la documentazione e i requisiti dichiarati. In caso di dati non veritieri, documentazione mancante o incoerente oppure scelta di una categoria senza i requisiti necessari, l’abbonamento potrà essere annullato, rettificato o sospeso senza rimborso.</p></div>
  <div class="panel"><h2 class="h3">Hai bisogno di assistenza?</h2><p class="small">In caso di problemi durante la registrazione, il caricamento dei documenti o l’acquisto, utilizza il servizio <a href="assistenza.html#assistenza">Richiesta di assistenza</a>.</p>
    <a class="btn btn-primary" href="{SHOP}">Richiedi l’abbonamento online {icon("external",16)}</a></div>
</div></section>'''
    ld = jsonld(ORG, {"@type": "HowTo", "name": "Come richiedere l’abbonamento studenti Linea 50", "step": [
        {"@type": "HowToStep", "name": "Registrati e completa il profilo", "text": "Crea il profilo del passeggero sul portale abbonamenti, scegli la categoria Studente – Ridotta 60% o 80% e carica i documenti richiesti."},
        {"@type": "HowToStep", "name": "Acquista l’abbonamento", "text": "Scegli l’abbonamento mensile o annuale, seleziona la fermata di partenza e Olbia come destinazione, completa il pagamento online."}]},
        breadcrumb_ld([("Home", "/"), ("Linee e orari", "/linee-e-orari"), ("Abbonamenti studenti", "/abbonamenti-studenti")]))
    return page(slug="abbonamenti", title="Abbonamenti studenti Linea 50 | Sun Lines",
                desc="Abbonamento studenti agevolato per la Linea 50 Olbia–Sant’Antonio di Gallura, fino a 27 anni: documenti necessari, tariffe Ridotta 60% e 80%, richiesta online in due passaggi.",
                canonical_path="/abbonamenti-studenti", active="linee", body=body, ld=ld, cta=(SHOP, "Richiedi online"))


